// Aggregate everything we know about the customer currently in the loop.
//
// THE RULE THIS NODE NOW OBEYS: NEVER EMIT A VALUE YOU COULD NOT READ.
//   A failed Gmail or Slack call arrives, thanks to onError
//   'continueRegularOutput', as an item carrying `error`. The old filters
//   (`i.json.id`, `i.json.ts || i.json.text`) dropped that item, `.length`
//   became 0, and 'Supabase - Upsert Profile' - which runs with
//   resolution=merge-duplicates - wrote that 0 straight over a previously
//   correct 47. A broken read and an empty inbox produced byte-identical
//   output. They no longer do: a count we could not measure is OMITTED FROM
//   THE PAYLOAD ENTIRELY, and PostgREST leaves a column that is not in the
//   body exactly as it found it.
const customer = $('Split In Batches').first().json || {};

function readCount(nodeName, keep) {
  let items;
  // $('Node') THROWS when the node did not run; only try/catch can rescue it.
  try { items = $(nodeName).all(); }
  catch (e) { return { ok: false, why: 'node did not run on this branch', count: null }; }
  if (!items.length) return { ok: false, why: 'node produced no items', count: null };
  for (const it of items) {
    const j = (it && it.json) || {};
    if (j.error !== undefined) {
      const m = (j.error && (j.error.message || j.error.description)) || j.error;
      return { ok: false, why: String(m).slice(0, 200), count: null };
    }
  }
  // alwaysOutputData turns a genuinely empty result into one empty item, which
  // `keep` discards - so a real zero still reads as a real zero.
  return { ok: true, why: null, count: items.filter(i => i.json && keep(i.json)).length };
}

const gmail = readCount('Gmail - Get Emails',      j => !!j.id);
const slack = readCount('Slack - Search Mentions', j => !!(j.ts || j.text));

// The directory (and the legacy Bitrix envelope) return false/'' for missing
// fields - normalise to null.
const clean = (v) => (v === false || v === 'false' || v === '' || v === undefined) ? null : v;

// APPLICABILITY is separate from SUCCESS. A customer with no real email was
// never asked about in Gmail at all: the node ran against a sentinel address
// so that $('Gmail - Get Emails') can never throw downstream, and its zero
// describes the sentinel, not the customer. Claiming it as "0 emails" would be
// asserting something we never tested, so that count is omitted too.
const mailKey  = clean(customer.mail_email);
const slackKey = clean(customer.mail_email) || clean(customer.phone);

const out = {
  customer_id: String(customer.id),
  name:  clean(customer.name),
  email: clean(customer.email),
  phone: clean(customer.phone),
  last_synced_at: new Date().toISOString()
};
if (mailKey  && gmail.ok) out.total_emails         = gmail.count;
if (slackKey && slack.ok) out.total_slack_messages = slack.count;

// The underscored keys are diagnostics for 'Delivery Report'. They are NOT
// columns: 'Supabase - Upsert Profile' builds its body from an explicit
// allowlist, so they can never reach PostgREST (an unknown column is a 400).
return [{ json: Object.assign(out, {
  _gmail_ok: gmail.ok, _gmail_why: gmail.why, _gmail_applicable: !!mailKey,
  _slack_ok: slack.ok, _slack_why: slack.why, _slack_applicable: !!slackKey
}) }];

// Accepts two shapes on purpose.
//
// 1. Supabase v_customer_directory - already {id, name, email, phone}. The HTTP
//    node may hand these over as one item per row, or as a single item holding
//    the whole array, depending on version; handle both.
// 2. The old Bitrix24 envelope - { result: [ {ID, NAME, EMAIL:[{VALUE}] ...} ] }.
//    Kept so that pointing the source back at the CRM needs no edit here.
//
// THE KEY-SPACE BUG THIS FIXES:
//   the old line was  String(r.id != null ? r.id : (r.email || ''))
//   so customer_360_profiles.customer_id - a UNIQUE column that
//   on_conflict=customer_id dedupes against - held EITHER a
//   v_customer_directory UUID OR an email address, two key spaces in one
//   column. The same human reachable under both keys got two profile rows, and
//   neither ever converged. Worse, a row with no id AND no email produced the
//   EMPTY STRING, so every such customer upserted onto one single shared
//   profile row, each night overwriting the last.
//   customer_id is now exactly one thing: the directory UUID. A row without one
//   is not synced at all - a profile keyed by something that is not an identity
//   is worse than no profile. The dormant Bitrix branch is namespaced
//   'bitrix:<ID>' so that reviving it can never collide with the UUID space.
const raw = $input.all().map(i => i.json);

// The Master Router synthesises '+<digits>@whatsapp.lead' for phone-only
// customers. It is a routing key, not a mailbox, and must never be handed to
// Gmail as a `from:` - see 'Gmail - Get Emails'.
const SYNTHETIC = /@whatsapp\.lead$/i;

function shape(id, name, email, phone) {
  const e = email || null;
  return {
    id: String(id),
    name: name || null,
    email: e,
    phone: phone || null,
    // The only address it is meaningful to search a mailbox for.
    mail_email: (e && !SYNTHETIC.test(e)) ? e : null
  };
}

if (raw.length === 1 && raw[0] && Array.isArray(raw[0].result)) {
  const first = (a) => Array.isArray(a) && a.length ? (a[0].VALUE || null) : null;
  return raw[0].result
    .filter(c => c && c.ID != null && String(c.ID) !== '')
    .map(c => ({ json: shape(
      'bitrix:' + String(c.ID),
      [c.NAME, c.LAST_NAME].filter(Boolean).join(' ').trim() || c.TITLE || null,
      first(c.EMAIL),
      first(c.PHONE)
    ) }))
    .filter(i => i.json.email || i.json.phone);
}

let rows = raw;
if (raw.length === 1 && Array.isArray(raw[0])) rows = raw[0];

return rows
  .filter(r => r && (r.email || r.phone))
  .filter(r => r.id != null && String(r.id) !== '')
  .map(r => ({ json: shape(
    r.id,
    r.name != null ? r.name : (r.customer_name || null),
    r.email,
    r.phone
  ) }));

// Every node whose success the Audit Log below is about to claim.
// Gmail / Slack are reads: losing them does not undo anything and the profile
// row still lands, so they are PARTIAL, not FAILED - but a count we could not
// measure must be NAMED, never hidden behind a plausible-looking number.
const CLAIMED = [
  { node: 'Supabase - Upsert Profile', what: 'customer_360_profiles upsert', critical: true },
  { node: 'Gmail - Get Emails',        what: 'Gmail history for this customer', critical: false },
  { node: 'Slack - Search Mentions',   what: 'Slack mentions for this customer', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return Object.assign({}, c, { ok: false, why: 'node did not run on this branch' }); }
  if (!items.length) return Object.assign({}, c, { ok: false, why: 'node produced no items' });
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = (j.error && (j.error.message || j.error.description)) || j.error;
    return Object.assign({}, c, { ok: false, why: String(m).slice(0, 300) });
  }
  return Object.assign({}, c, { ok: true });
}

const results  = CLAIMED.map(check);
const dropped  = results.filter(r => !r.ok);
const fatal    = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

// The upsert runs with Prefer: return=minimal, so its own output carries no
// profile fields. Read them back from the node that built them.
let profile = {};
try { profile = $('Transform & Unify').first().json || {}; } catch (e) { profile = {}; }

// A read that ERRORED is not a read that found NOTHING, and a channel we never
// queried is neither. 'Transform & Unify' now decides all three cases BEFORE
// the write and simply omits an unmeasured count from the upsert body, so the
// stored value survives untouched instead of being flattened to 0. This node no
// longer has to apologise for a number that was already written - it only has
// to describe what happened.
const gmailOk  = !!profile._gmail_ok;
const slackOk  = !!profile._slack_ok;
const gmailApp = !!profile._gmail_applicable;
const slackApp = !!profile._slack_applicable;

// Both source nodes fetch at most 20 items, so any count is 'up to 20'. Say so
// rather than let a 20 read as a total.
const cap = (n) => (n >= 20 ? n + '+ (source capped at 20)' : String(n));

const emailsTxt = !gmailApp
  ? 'email count NOT APPLICABLE - customer has no real email address, Gmail was not queried'
  : (gmailOk ? (cap(profile.total_emails ?? 0) + ' email(s)')
             : 'email count UNKNOWN - Gmail read failed, previous stored value left intact');
const slackTxt = !slackApp
  ? 'Slack count NOT APPLICABLE - customer has no searchable identity'
  : (slackOk ? (cap(profile.total_slack_messages ?? 0) + ' Slack mention(s)')
             : 'Slack count UNKNOWN - Slack read failed, previous stored value left intact');

// Each reason is trimmed so the whole line survives the 500-char audit summary.
// The reason string is the only place the ACTUAL API error text is ever written
// down anywhere - execution data is pruned, and both nodes swallow their error.
const reasons = dropped.map(r => r.what + ' - ' + String(r.why).slice(0, 90));

const note = dropped.length
  ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
  : 'all ' + results.length + ' claimed steps verified';

const audit_summary = ('Profile upsert - ' + emailsTxt + ', ' + slackTxt + '. ' + note
  + (reasons.length ? ': ' + reasons.join(' | ') : '')).substring(0, 500);

return [{ json: {
  ...profile,
  ...( $input.first().json || {} ),
  // null, not 0: we do not know, and 0 is an assertion. Unlike before, this is
  // now only a REPORTING choice - nothing zeroed was ever written.
  total_emails:         (gmailOk && gmailApp) ? (profile.total_emails ?? null) : null,
  total_slack_messages: (slackOk && slackApp) ? (profile.total_slack_messages ?? null) : null,
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  reasons,
    note,
    audit_summary,
  },
} }];
